(function(){
  const BG="data:image/webp;base64,[... ELLIPSIZATION ...]";
  function apply(){
    const h=document.getElementById("qmes-erp-header");
    if(!h)return;
    h.style.setProperty("background-image",'url("'+BG+'")',"important");
    h.style.setProperty("background-position","center center","important");
    h.style.setProperty("background-size","cover","important");
    h.style.setProperty("background-repeat","no-repeat","important");
    h.style.setProperty("background-color","#173b63","important");
    const logo=h.querySelector(".qh-logo");
    if(logo){logo.style.setProperty("display","block","important");logo.style.setProperty("opacity","1","important");logo.style.setProperty("visibility","visible","important");logo.style.setProperty("width","232px","important");}
  }
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",()=>{setTimeout(apply,0);setTimeout(apply,300);},{once:true});else{setTimeout(apply,0);setTimeout(apply,300);}
  new MutationObserver(apply).observe(document.documentElement,{childList:true,subtree:true});
})();